const version = await \(await fetch\('http://127.0.0.1:9222/json/version'\)\).json\(\);
const ws = new WebSocket\(version.webSocketDebuggerUrl\);
await new Promise\(\(res, rej\) => { ws.onopen = res; ws.onerror = rej; }\);
let seq = 0; const pending = new Map\(\);
ws.onmessage = \(e\) => { const m = JSON.parse\(e.data\); if \(m.id\) { const p = pending.get\(m.id\); if \(p\) { pending.delete\(m.id\); m.error ? p.rej\(new Error\(JSON.stringify\(m.error\)\)\) : p.res\(m.result\); } } };
const send = \(method, params = {}, sessionId\) => new Promise\(\(res, rej\) => { const id = ++seq; pending.set\(id, { res, rej }\); ws.send\(JSON.stringify\({ id, method, params, ...\(sessionId ? { sessionId } : {}\) }\)\); }\);
const sleep = \(ms\) => new Promise\(r => setTimeout\(r, ms\)\);
const { targetId } = await send\('Target.createTarget', { url: 'about:blank' }\);
const { sessionId: S } = await send\('Target.attachToTarget', { targetId, flatten: true }\);
await send\('Page.enable', {}, S\); await send\('Runtime.enable', {}, S\);
await send\('Emulation.setDeviceMetricsOverride', { width: 1440, height: 1000, deviceScaleFactor: 1, mobile: false }, S\);
await send\('Page.navigate', { url: 'http://localhost:8123/' }, S\);
await sleep\(4000\);
const ev = async \(expression\) => { const r = await send\('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true }, S\); if \(r.exceptionDetails\) throw new Error\(r.exceptionDetails.text\); return r.result.value; };
await ev\(`document.documentElement.dataset.theme = 'dark'`\);
await sleep\(400\);
console.log\(await ev\(`JSON.stringify\({
  navOn: \(\(\) => { const el = document.querySelector\('.app-nav a.on'\); const s = getComputedStyle\(el\); return { bg: s.backgroundColor, color: s.color, cls: el.className }; }\)\(\),
  switchOn: \(\(\) => { const el = document.querySelector\('.app-switch .on'\); const s = getComputedStyle\(el\); return { bg: s.backgroundColor, color: s.color }; }\)\(\),
  sidebar: getComputedStyle\(document.querySelector\('.app-sidebar'\)\).backgroundColor,
  chat: getComputedStyle\(document.querySelector\('.app-chat'\)\).backgroundColor,
  chatImage: getComputedStyle\(document.querySelector\('.app-chat'\)\).backgroundImage,
  appStat: getComputedStyle\(document.querySelector\('.app-stat'\)\).backgroundColor,
  appStatBorder: getComputedStyle\(document.querySelector\('.app-stat'\)\).borderColor,
  newTaskParent: document.querySelector\('.app-nav a.on'\).outerHTML.slice\(0, 120\)
}\)`\)\);
await send\('Target.closeTarget', { targetId }\);
ws.close\(\);
process.exit\(0\);
