  location.reload\(\);
  await new Promise\(r => setTimeout\(r, 3000\)\);
  return JSON.stringify\({ before, after: document.documentElement.dataset.theme, stored: localStorage.getItem\('fantin-theme'\), meta: document.querySelector\('meta[name="theme-color"]'\)?.content }\);
}\)\(\)`\)\);
